[CmdletBinding()]param([Parameter(Mandatory)][ValidateSet('deploy-plan','deploy-preview','deploy-validate','deploy-request-approval','deploy-backup','deploy-apply','deploy-verify','deploy-rollback','deploy-status','deploy-fail')][string]$Operation,[string]$TaskId,[string]$ArtifactPath,[string]$ManifestPath,[string]$TargetId,[string]$StoreRoot=(Join-Path $PSScriptRoot 'Store'),[switch]$DryRun)
$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'Repato.Deployment.psm1') -Force
if($Operation -eq 'deploy-plan'){New-DeployPlan $StoreRoot $TaskId $ArtifactPath $ManifestPath $TargetId -DryRun:$DryRun|ConvertTo-Json -Depth 10}else{if($Operation -eq 'deploy-status'){Get-DeployStatus $StoreRoot $TaskId|ConvertTo-Json -Depth 10}else{throw 'Deployment operations are dry-run only in this version.'}}
